  `new_code_grade` varchar(20) DEFAULT NULL,
  `new_indice` int DEFAULT NULL,
  `new_date_d_effet` date DEFAULT NULL,
  `num_visa_finance` varchar(100) DEFAULT NULL,
  `date_visa_finance` date DEFAULT NULL,
  `num_visa_cde` varchar(100) DEFAULT NULL,
  `date_visa_cde` date DEFAULT NULL,
  `nom_signataire` varchar(255) DEFAULT NULL,
  `corps_signataire` varchar(255) DEFAULT NULL,
  `date_generation` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
