--
-- Déclencheurs `personnel_etat_civil`
--
DROP TRIGGER IF EXISTS `after_etat_civil_insert`;
DELIMITER $$
CREATE TRIGGER `after_etat_civil_insert` AFTER INSERT ON `personnel_etat_civil` FOR EACH ROW BEGIN
    IF NEW.date_naiss IS NOT NULL THEN
        UPDATE personnel_fpe 
        SET date_naissance = NEW.date_naiss 
        WHERE im = NEW.im;
    END IF;
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `after_etat_civil_update`;
DELIMITER $$
CREATE TRIGGER `after_etat_civil_update` AFTER UPDATE ON `personnel_etat_civil` FOR EACH ROW BEGIN
    IF NEW.date_naiss IS NOT NULL THEN
        UPDATE personnel_fpe 
        SET date_naissance = NEW.date_naiss 
        WHERE im = NEW.im;
    END IF;
END
$$
DELIMITER ;

