CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_moteur_alertes`  AS WITH     `progression_carriere` as (select `psa`.`im` AS `im`,`psa`.`statut_actuel` AS `statut_actuel`,`psa`.`categorie_actuel` AS `categorie_actuel`,`psa`.`type_acte_actuel` AS `type_acte_actuel`,`rc`.`id` AS `corps_id`,`rg`.`id` AS `grade_id_actuel`,`rg`.`libelle_grade` AS `grade_nom_actuel`,`rg`.`modele_id` AS `modele_id`,(case when ((`psa`.`type_avancement_actuel` = 'Intégration') and (`psa`.`categorie_actuel` in ('IV','V','VI','VIII'))) then coalesce((select `pa_prev`.`av_date_effet` from `personnel_avancements` `pa_prev` where ((`pa_prev`.`im` = `psa`.`im`) and (`pa_prev`.`av_date_effet` < (select `pa_intg`.`av_date_effet` from `personnel_avancements` `pa_intg` where ((`pa_intg`.`im` = `psa`.`im`) and (`pa_intg`.`av_type_avancement` = 'Intégration')) order by `pa_intg`.`av_date_effet` desc,`pa_intg`.`id` desc limit 1))) order by `pa_prev`.`av_date_effet` desc,`pa_prev`.`id` desc limit 1),`psa`.`date_d_effet_actuel`) else `psa`.`date_d_effet_actuel` end) AS `date_effet_etape`,`rg`.`duree_annees` AS `duree_pour_prochain_palier`,1 AS `palier_niveau` from ((`personnel_situation_actuelle` `psa` join `ref_grades_types` `rg` on((`psa`.`grade_actuel` = `rg`.`libelle_grade`))) join `ref_corps` `rc` on(((`psa`.`corps_actuel` = `rc`.`libelle_corps`) and (`rc`.`modele_id` = `rg`.`modele_id`)))) where (((`psa`.`statut_actuel` = 'Contractuel EFA') and (left(`psa`.`code_corps_actuel`,1) = 'U')) or ((`psa`.`statut_actuel` = 'Fonctionnaire') and (left(`psa`.`code_corps_actuel`,1) in ('A','B','C')))) union all select `pc`.`im` AS `im`,`pc`.`statut_actuel` AS `statut_actuel`,`pc`.`categorie_actuel` AS `categorie_actuel`,`pc`.`type_acte_actuel` AS `type_acte_actuel`,`pc`.`corps_id` AS `corps_id`,`rg_next`.`id` AS `id`,`rg_next`.`libelle_grade` AS `libelle_grade`,`rg_next`.`modele_id` AS `modele_id`,(`pc`.`date_effet_etape` + interval (case when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'contrat')) then 1 when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'avenant')) then 2 else `pc`.`duree_pour_prochain_palier` end) year) AS `DATE_ADD(pc.date_effet_etape, INTERVAL (
            CASE 
                WHEN pc.statut_actuel = 'Contractuel EFA' 
                 AND pc.grade_nom_actuel = '2°CLASSE/2°ECHELON' 
                 AND pc.categorie_actuel IN ('IV', 'V', 'VI', 'VII`,`rg_next`.`duree_annees` AS `duree_annees`,(`pc`.`palier_niveau` + 1) AS `pc.palier_niveau + 1` from (`progression_carriere` `pc` join `ref_grades_types` `rg_next` on(((`rg_next`.`modele_id` = `pc`.`modele_id`) and (`rg_next`.`id` = (`pc`.`grade_id_actuel` + 1))))) where ((`pc`.`date_effet_etape` + interval (case when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'contrat')) then 1 when ((`pc`.`statut_actuel` = 'Contractuel EFA') and (`pc`.`grade_nom_actuel` = '2°CLASSE/2°ECHELON') and (`pc`.`categorie_actuel` in ('IV','V','VI','VIII')) and (lower(`pc`.`type_acte_actuel`) = 'avenant')) then 2 else `pc`.`duree_pour_prochain_palier` end) year) <= curdate())) select `alertes_finales`.`alerte_id` AS `alerte_id`,`alertes_finales`.`im` AS `im`,`alertes_finales`.`titre` AS `titre`,`alertes_finales`.`message` AS `message`,`alertes_finales`.`date_reception_technique` AS `date_reception_technique`,`alertes_finales`.`couleur_code` AS `couleur_code`,`alertes_finales`.`icone` AS `icone`,`alertes_finales`.`type_key` AS `type_key`,`alertes_finales`.`nb_paliers_retard` AS `nb_paliers_retard` from (select (concat(`pc`.`im`,'_AVANCEMENT_GROUPE') collate utf8mb4_0900_ai_ci) AS `alerte_id`,`pc`.`im` AS `im`,(concat(count(0),(case when (`pc`.`statut_actuel` = 'Contractuel EFA') then ' AVENANT(S) EN RETARD' else ' AVANCEMENT(S) EN RETARD' end)) collate utf8mb4_0900_ai_ci) AS `titre`,(concat((case when (count(0) > 1) then 'Vous êtes éligible aux avancements suivants : \n' else 'Vous êtes éligible à l\'avancement suivant : \n ' end),group_concat(concat('• ',`pc`.`grade_nom_actuel`,' (depuis le ',date_format(`pc`.`date_effet_etape`,'%d/%m/%Y'),')') separator '\n'),'\n Vous pouvez récupérer les pièces du dossier à constituer ici et passer au responsable de votre CISCO ou DREN pour finaliser la demande après.') collate utf8mb4_0900_ai_ci) AS `message`,min(`pc`.`date_effet_etape`) AS `date_reception_technique`,'sky' AS `couleur_code`,'fas fa-step-forward' AS `icone`,('ECHELON' collate utf8mb4_0900_ai_ci) AS `type_key`,count(0) AS `nb_paliers_retard` from `progression_carriere` `pc` where ((`pc`.`palier_niveau` > 1) and ((`pc`.`statut_actuel` <> 'Fonctionnaire') or (`pc`.`grade_nom_actuel` <> '2°CLASSE/1°ECHELON') or (`pc`.`palier_niveau` <> 2))) group by `pc`.`im`,`pc`.`statut_actuel` having (count(0) > 0) union all select (concat('HIDDEN_',`pc`.`im`,'_AVANCEMENT_',`pc`.`palier_niveau`) collate utf8mb4_0900_ai_ci) AS `CONCAT('HIDDEN_', pc.im, '_AVANCEMENT_', pc.palier_niveau) COLLATE utf8mb4_0900_ai_ci`,`pc`.`im` AS `im`,`pc`.`grade_nom_actuel` AS `grade_nom_actuel`,`pc`.`grade_nom_actuel` AS `grade_nom_actuel`,`pc`.`date_effet_etape` AS `date_effet_etape`,'slate' AS `slate`,'fas fa-eye-slash' AS `fas fa-eye-slash`,'ECHELON_DETAIL' AS `ECHELON_DETAIL`,1 AS `1` from `progression_carriere` `pc` where ((`pc`.`palier_niveau` > 1) and ((`pc`.`statut_actuel` <> 'Fonctionnaire') or (`pc`.`grade_nom_actuel` <> '2°CLASSE/1°ECHELON') or (`pc`.`palier_niveau` <> 2))) union all select (concat(`personnel_situation_actuelle`.`im`,'_INTG') collate utf8mb4_0900_ai_ci) AS `CONCAT(im, '_INTG') COLLATE utf8mb4_0900_ai_ci`,`personnel_situation_actuelle`.`im` AS `im`,'Demande d\'Intégration' AS `Demande d'Intégration`,concat('Vous êtes éligible à l\'intégration depuis le ',date_format((`personnel_situation_actuelle`.`date_entree_admin` + interval 6 year),'%d/%m/%Y'),', Veuillez passer au responsable du personnel encadré pour constituer votre dossier.') AS `CONCAT("Vous êtes éligible à l'intégration depuis le ", DATE_FORMAT(DATE_ADD(date_entree_admin, INTERVAL 6 YEAR), '%d/%m/%Y'), ", Veuillez passer au responsable du personnel encadré pour constituer votre dossier.")`,(`personnel_situation_actuelle`.`date_entree_admin` + interval 6 year) AS `DATE_ADD(date_entree_admin, INTERVAL 6 YEAR)`,'purple' AS `purple`,'fas fa-fingerprint' AS `fas fa-fingerprint`,'INTG' AS `INTG`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Contractuel EFA') and (left(`personnel_situation_actuelle`.`code_corps_actuel`,1) = 'U') and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 6 year) <= curdate())) union all select (concat(`personnel_situation_actuelle`.`im`,'_TITU') collate utf8mb4_0900_ai_ci) AS `CONCAT(im, '_TITU') COLLATE utf8mb4_0900_ai_ci`,`personnel_situation_actuelle`.`im` AS `im`,'Demande de Titularisation' AS `Demande de Titularisation`,concat('Vous êtes éligible à la titularisation depuis le ',date_format((`personnel_situation_actuelle`.`date_d_effet_actuel` + interval 1 year),'%d/%m/%Y'),', Veuillez passer au responsable du personnel encadré pour constituer votre dossier.') AS `CONCAT("Vous êtes éligible à la titularisation depuis le ", DATE_FORMAT(DATE_ADD(date_d_effet_actuel, INTERVAL 1 YEAR), '%d/%m/%Y'), ", Veuillez passer au responsable du personnel encadré pour constituer votre dossier.")`,(`personnel_situation_actuelle`.`date_d_effet_actuel` + interval 1 year) AS `DATE_ADD(date_d_effet_actuel, INTERVAL 1 YEAR)`,'indigo' AS `indigo`,'fas fa-medal' AS `fas fa-medal`,'TITU' AS `TITU`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Fonctionnaire') and (`personnel_situation_actuelle`.`grade_actuel` = 'STAGIAIRE') and ((`personnel_situation_actuelle`.`date_d_effet_actuel` + interval 1 year) <= curdate())) union all select (concat(`personnel_situation_actuelle`.`im`,'_RNC1') collate utf8mb4_0900_ai_ci) AS `CONCAT(im, '_RNC1') COLLATE utf8mb4_0900_ai_ci`,`personnel_situation_actuelle`.`im` AS `im`,'Renouvellement du 1er contrat' AS `Renouvellement du 1er contrat`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day) <= curdate()) then concat('Votre 1er contrat a EXPIRÉ le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day),'%d/%m/%Y'),'. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') else concat('Votre 1er contrat finit le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day),'%d/%m/%Y'),'. Il vous reste ',(period_diff(extract(year_month from ((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day)),extract(year_month from curdate())) - if((dayofmonth(curdate()) > dayofmonth(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day))),1,0)),' mois et ',((to_days(((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day)) - to_days(curdate())) % 30),' jours. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') end) AS `message`,(`personnel_situation_actuelle`.`date_entree_admin` + interval 12 month) AS `date_reception_technique`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month) - interval 1 day) <= curdate()) then 'red' else 'orange' end) AS `CASE WHEN DATE_SUB(DATE_ADD(date_entree_admin, INTERVAL 24 MONTH), INTERVAL 1 DAY) <= CURRENT_DATE THEN 'red' ELSE 'orange' END`,'fas fa-file-contract' AS `fas fa-file-contract`,'CONTRAT' AS `CONTRAT`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Contractuel EFA') and (left(`personnel_situation_actuelle`.`code_corps_actuel`,1) in ('L','K','J')) and (`personnel_situation_actuelle`.`date_d_effet_actuel` < (`personnel_situation_actuelle`.`date_entree_admin` + interval 24 month)) and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 12 month) <= curdate()) and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 36 month) > curdate())) union all select (concat(`personnel_situation_actuelle`.`im`,'_RNC2') collate utf8mb4_0900_ai_ci) AS `CONCAT(im, '_RNC2') COLLATE utf8mb4_0900_ai_ci`,`personnel_situation_actuelle`.`im` AS `im`,'Renouvellement du 2ème contrat' AS `Renouvellement du 2ème contrat`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day) <= curdate()) then concat('Votre 2ème contrat a EXPIRÉ le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day),'%d/%m/%Y'),'. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') else concat('Votre 2ème contrat finit le ',date_format(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day),'%d/%m/%Y'),'. Il vous reste ',(period_diff(extract(year_month from ((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day)),extract(year_month from curdate())) - if((dayofmonth(curdate()) > dayofmonth(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day))),1,0)),' mois et ',((to_days(((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day)) - to_days(curdate())) % 30),' jours. Veuillez passer au responsable du personnel non encadré pour constituer votre dossier de renouvellement de contrat.') end) AS `message`,(`personnel_situation_actuelle`.`date_entree_admin` + interval 36 month) AS `date_reception_technique`,(case when (((`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month) - interval 1 day) <= curdate()) then 'red' else 'orange' end) AS `CASE WHEN DATE_SUB(DATE_ADD(date_entree_admin, INTERVAL 48 MONTH), INTERVAL 1 DAY) <= CURRENT_DATE THEN 'red' ELSE 'orange' END`,'fas fa-file-contract' AS `fas fa-file-contract`,'CONTRAT' AS `CONTRAT`,1 AS `1` from `personnel_situation_actuelle` where ((`personnel_situation_actuelle`.`statut_actuel` = 'Contractuel EFA') and (left(`personnel_situation_actuelle`.`code_corps_actuel`,1) in ('L','K','J')) and (`personnel_situation_actuelle`.`date_d_effet_actuel` < (`personnel_situation_actuelle`.`date_entree_admin` + interval 48 month)) and ((`personnel_situation_actuelle`.`date_entree_admin` + interval 36 month) <= curdate())) union all select (concat(`pec`.`im`,'_ADMISSION_RETRAITE') collate utf8mb4_0900_ai_ci) AS `id_alerte`,`pec`.`im` AS `im`,'Demande d\'arrêté d\'admission à la retraite' AS `titre`,'Vous êtes à la veille de la retraite, vous pouvez demander l\'arrêté d\'admission à la retraite à partir d\'aujourd\'hui, veuillez passer au responsable de votre cisco pour soumettre la demande.' AS `message`,((`pec`.`date_naiss` + interval 60 year) - interval 1 year) AS `date_reception_technique`,(case when ((`pec`.`date_naiss` + interval 60 year) <= curdate()) then 'red' else 'orange' end) AS `couleur`,'fas fa-user-clock' AS `icone`,'ADMISSION_RETRAITE' AS `type_alerte`,1 AS `statut` from `personnel_etat_civil` `pec` where (((`pec`.`date_naiss` + interval 60 year) <= (curdate() + interval 1 year)) and exists(select 1 from `suivi_agents_bordereau` `s_chk` where ((`s_chk`.`im_agent` = `pec`.`im`) and (`s_chk`.`type_bordereau` = 'admission_retraite') and (`s_chk`.`statut_finale` = 'valide'))) is false) union all select (concat(`personnel_etat_civil`.`im`,'_COMPENSATRICE') collate utf8mb4_0900_ai_ci) AS `id_alerte`,`personnel_etat_civil`.`im` AS `im`,'Demande de décision de compensatrice' AS `titre`,'Vous êtes élligible pour demander la decision d\'octroi de compensatrice des congés non pris si vous avez l\'arrêté d\'amission à la retraite.' AS `message`,((`personnel_etat_civil`.`date_naiss` + interval 60 year) - interval 1 year) AS `date_reception_technique`,(case when ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= curdate()) then 'red' else 'orange' end) AS `couleur`,'fas fa-file-invoice-dollar' AS `icone`,'COMPENSATRICE' AS `type_alerte`,1 AS `statut` from `personnel_etat_civil` where ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= (curdate() + interval 1 year)) union all select (concat(`personnel_etat_civil`.`im`,'_INSTALLATION') collate utf8mb4_0900_ai_ci) AS `id_alerte`,`personnel_etat_civil`.`im` AS `im`,'Demande de décision d\'installation' AS `titre`,'Vous êtes élligible de demander la decision d\'installation lorsque vous obtendrez l\'arrêté d\'admission à la retraite.' AS `message`,((`personnel_etat_civil`.`date_naiss` + interval 60 year) - interval 1 year) AS `date_reception_technique`,(case when ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= curdate()) then 'red' else 'orange' end) AS `couleur`,'fas fa-truck-loading' AS `icone`,'INSTALLATION' AS `type_alerte`,1 AS `statut` from `personnel_etat_civil` where ((`personnel_etat_civil`.`date_naiss` + interval 60 year) <= (curdate() + interval 1 year)) union all select (concat(`u`.`im`,'_BORD_DREN_',`b`.`id`) collate utf8mb4_0900_ai_ci) AS `id`,`u`.`im` AS `im`,'Bordereau en attente de traitement' AS `titre`,concat('Le bordereau n° ',`b`.`numero_complet`,' du ',date_format(`b`.`date_envoi_bordereau`,'%d/%m/%Y'),', transmis par le ',(case when (`b`.`type_etablissement` = 'CISCO') then concat('CISCO ',coalesce(`b`.`expediteur`,'')) when (`b`.`type_etablissement` = 'CRFRP') then coalesce(`b`.`expediteur`,'') else coalesce(`b`.`expediteur`,'') end),', contient ',((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1),if((((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1) > 1),' dossiers d’agents relatifs à une demande de création de projet ',' dossier d’agent relatif à une demande de création de projet '),(case `b`.`type_demande` when 'renouvellement' then 'de renouvellement de contrat' when 'avenant' then 'd\'avenant' when 'avancement_classe' then 'd\'avancement de classe et d\'echelon' when 'avancement_echelon' then 'd\'avancement d\'echelon' when 'integration' then 'd\'intégration' when 'titularisation' then 'de titularisation' when 'admission_retraite' then 'd\'admission à la retraite' when 'compensatrice' then 'd\'indemnité compensatrice' when 'installation' then 'd\'indemnité d\'installation' else coalesce(`b`.`type_demande`,'') end),'. Veuillez : \n • accéder au menu « Référence des dossiers » pour attribuer une référence au bordereau, \n • puis accéder au menu « Traitement des dossiers » afin de traiter ',if((((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1) > 1),'les dossiers des agents concernés.','le dossier de l’agent concerné.')) AS `message`,`b`.`date_envoi_bordereau` AS `date_reception_technique`,'orange' AS `couleur`,'fas fa-folder-open' AS `icone`,'BORDEREAU' AS `categorie`,1 AS `statut` from (((((`archives_bordereaux_dren` `b` left join `ref_crfrp` `c` on(((`b`.`type_etablissement` = 'CRFRP') and (`c`.`nom_crfrp` = `b`.`expediteur`)))) left join `ref_districts` `d_crfrp` on(((`b`.`type_etablissement` = 'CRFRP') and (`d_crfrp`.`id` = `c`.`district_id`)))) left join `ref_districts` `d_cisco` on(((`b`.`type_etablissement` = 'CISCO') and (`d_cisco`.`nom_district` = `b`.`expediteur`)))) left join `ref_regions` `r` on((`r`.`id` = coalesce(`d_crfrp`.`region_id`,`d_cisco`.`region_id`)))) join `utilisateurs` `u` on(((`u`.`niveau` = 'regional') and (lower(`u`.`code_lieu_affectation`) = lower(`r`.`nom_region`)) and (`u`.`role_specifique` = (case when (`b`.`type_demande` in ('renouvellement','avenant','integration')) then 'resp_non_encadre' when (`b`.`type_demande` in ('titularisation','avancement_echelon','avancement_classe','admission_retraite')) then 'resp_encadre' else NULL end))))) where (`b`.`statut_bordereau` = 'en_attente') union all select (concat(`u`.`im`,'_BORD_DRH_',`b`.`id`) collate utf8mb4_0900_ai_ci) AS `id`,`u`.`im` AS `im`,'Bordereau en attente de traitement (DRH)' AS `titre`,concat('Le bordereau n° ',`b`.`numero_complet`,' du ',date_format(`b`.`date_envoi_bordereau`,'%d/%m/%Y'),', transmis par la DREN ',coalesce(`b`.`expediteur`,'DREN'),', contient ',((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1),if((((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1) > 1),' dossiers d’agents relatifs à une demande ',' dossier d’agent relatif à une demande '),(case `b`.`type_demande` when 'integration' then 'd\'intégration' when 'titularisation' then 'de titularisation' else coalesce(`b`.`type_demande`,'') end),'. Veuillez : \n • accéder au menu « Référence des dossiers » pour attribuer une référence au bordereau, \n • puis accéder au menu « Traitement des dossiers » afin de traiter ',if((((char_length(`b`.`liste_agents`) - char_length(replace(`b`.`liste_agents`,',',''))) + 1) > 1),'les dossiers des agents concernés.','le dossier de l’agent concerné.')) AS `message`,`b`.`date_envoi_bordereau` AS `date_reception_technique`,'purple' AS `couleur`,'fas fa-folder-open' AS `icone`,'BORDEREAU' AS `categorie`,1 AS `statut` from (`archives_bordereaux_drh` `b` join `utilisateurs` `u` on(((`u`.`niveau` = 'central') and (`u`.`role_specifique` = (case when (`b`.`type_demande` = 'integration') then 'resp_non_encadre' when (`b`.`type_demande` = 'titularisation') then 'resp_encadre' else NULL end))))) where ((`b`.`statut_bordereau` = 'en_attente') and (`b`.`type_demande` in ('integration','titularisation'))) union all select (concat(`s`.`im_agent`,'_STEP_DREN_',`s`.`id`) collate utf8mb4_0900_ai_ci) AS `CONCAT(s.im_agent, '_STEP_DREN_', s.id) COLLATE utf8mb4_0900_ai_ci`,`s`.`im_agent` AS `im_agent`,'Dépôt de dossier à la DREN' AS `Dépôt de dossier à la DREN`,concat('Votre demande ',(case when (`s`.`type_bordereau` = 'renouvellement') then 'de renouvellement de contrat' when (`s`.`type_bordereau` = 'avenant') then 'd\'avenant' when (`s`.`type_bordereau` = 'avancement_classe') then 'd\'avancement de classe et d\'echelon' when (`s`.`type_bordereau` = 'avancement_echelon') then 'd\'avancement