INSERT INTO `configuration_arrete` (`id`, `region`, `corps_id`, `type_avancement`, `texte`, `updated_at`) VALUES
(1, 'BOENY', 11, 'classe', 'Vu la Constitution ;\r\nVu la décision n°10-HCC/D3 du 14 Octobre 2025 accordant à l’autorité militaire compétente, représentée par le Colonel RANDRIANIRINA Michael, l’exercice des fonctions de Chef de l’Etat ;\r\nVu la Loi n° 2003-011 du 03 Septembre 2003, relative au statut général des fonctionnaires ;\r\nVu le Décret n°96-749 du 20 février 2019, créant un corps des CONCEPTEURS et fixant le régime particulier de ce corps et les textes subséquents\r\nVu le Décret N°2014-1929 du 23 Décembre 2014 fixant les modalités d’application de certaines dispositions de la Loi N°2014-021 du 12 Septembre 2014 relative à la représentation de l’État ;\r\nVu le Décret N°2015-593 du 01 Avril 2015 portant création des Circonscriptions Administratives ;\r\nVu le Décret N°2015-1331 du 28 Septembre 2015 fixant les pouvoirs délégués en matière de gestion du personnel de l’État aux Ministres et aux Préfets ;\r\nVu le Décret n°2025-1101 du 20 Octobre 2025, portant nomination du Premier Ministre, Chef du Gouvernement ;\r\nVu le Décret n°2025-1114 du 28 Octobre 2025, portant nomination des membres du Gouvernement ;\r\nVu la Décision n°___________/${annee_chiffre}-PREF/MNJ du ________________ portant dans inscription au tableau d’avancement de Classe d’un fonctionnaire du corps des CONCEPTEURS ;\r\nVu le Décret n° 2025-1652 du 08 Décembre 2025 portant nomination du Préfet de Mahajanga ;\r\nVu le Procès-verbal de réunion de la Commission Administrative Paritaire dans le corps concerné en date du ___________________\r\nVu le Dossier de l’intéressée ;', '2026-08-26 07:04:02'),
(3, 'BOENY', 11, 'echelon', 'Vu la Constitution ;\r\nVu la décision n°10-HCC/D3 du 14 Octobre 2025 accordant à l’autorité militaire compétente, représentée par le Colonel RANDRIANIRINA Michael, l’exercice des fonctions de Chef de l’Etat ;\r\nVu la loi n° 2003-011 du 03 Septembre 2003, relative au statut général des fonctionnaires ;\r\nVu le décret n°96-746 du 27 Aout 1996, créant un corps des CONCEPTEURS et fixant le régime particulier de ce corps et les textes subséquents ;\r\nVu le décret N°2014-1929 du 23 Décembre 2014 fixant les modalités d’application de certaines dispositions de la Loi N°2014-021 du 12 Septembre 2014 relative à la représentation de l’État ;\r\nVu le décret N°2015-1331 du 28 Septembre 2015 fixant les pouvoirs délégués en matière de gestion du personnel de l’État aux Ministres et aux Préfets ;\r\nVu le décret N°2025-1652 du 08 Décembre 2025 portant nomination du Préfet de Mahajanga ;\r\nVu décret n° 2026-776 du 15 Mars 2026, portant nomination du Premier Ministre, Chef du Gouvernement ;\r\nVu le décret n°2026-777 du 25 Mars 2026, portant nomination des membres du gouvernement ; \r\nVu le dossier de l’intéressé ;', '2026-08-26 06:11:27'),
