(2, '292903_ADMISSION_RETRAITE', '292903', 'admission_retraite', 'Vous êtes à la veille de la retraite, vous pouvez demander l\'arrêté d\'admission à la retraite à partir d\'aujourd\'hui, veuillez passer au responsable de votre cisco pour soumettre la demande.', 0, '2026-10-01 10:06:57'),
(3, '390390_ADMISSION_RETRAITE', '390390', 'admission_retraite', 'Vous êtes à la veille de la retraite, vous pouvez demander l\'arrêté d\'admission à la retraite à partir d\'aujourd\'hui, veuillez passer au responsable de votre cisco pour soumettre la demande.', 0, '2026-10-01 10:07:02'),
(4, '504026_ADMISSION_RETRAITE', '504026', 'admission_retraite', 'Vous êtes à la veille de la retraite, vous pouvez demander l\'arrêté d\'admission à la retraite à partir d\'aujourd\'hui, veuillez passer au responsable de votre cisco pour soumettre la demande.', 0, '2026-10-01 10:07:07'),
(5, '292903_COMPENSATRICE', '292903', 'compensatrice', 'Vous êtes élligible pour demander la decision d\'octroi de compensatrice des congés non pris si vous avez l\'arrêté d\'amission à la retraite.', 0, '2026-10-01 10:07:12'),
(6, '390390_COMPENSATRICE', '390390', 'compensatrice', 'Vous êtes élligible pour demander la decision d\'octroi de compensatrice des congés non pris si vous avez l\'arrêté d\'amission à la retraite.', 0, '2026-10-01 10:07:18'),
